{
  "question_num": 2,
  "total_marks": 8,
  "title": "Upthrust and Falling Sphere",
  "main_stem": "A high-altitude balloon is stationary in still air. A solid sphere is suspended from the balloon by a string, as shown in Fig. 2.1.\n\nFig. 2.1 (not to scale)\n\nThe volume of the balloon is $7.5\\text{m}^3$. The total weight of the balloon, string and sphere is $65\\text{ N}$. The upthrust acting on the string and sphere is negligible.",
  "parts": [
    {
      "label": "(a)",
      "part_stem": null,
      "text": "Calculate the density of the air surrounding the balloon.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(i)",
      "part_stem": "The string breaks, releasing the sphere.",
      "text": "State the magnitude of the acceleration of the sphere immediately after the string breaks.",
      "marks": 1,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(ii)",
      "part_stem": null,
      "text": "State and explain the variation, if any, in the magnitude of the acceleration of the sphere when it is moving downwards before it reaches terminal (constant) velocity.",
      "marks": 3,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(c)",
      "part_stem": "The sphere has a mass of $4.0\\text{ kg}$.",
      "text": "Calculate the total resistive force acting on the sphere at the instant when its acceleration is $1.9\\text{ m s}^{-2}$.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    }
  ],
  "markscheme": [
    {
      "label": "(a)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "C1",
          "text": "$65 = \\rho gV$ or $65 = mg$ and $m = \\rho V$"
        },
        {
          "tag": "A1",
          "text": "$\\rho = 65 / (9.81 \\times 7.5)$ $= 0.88\\text{ kg m}^{-3}$"
        }
      ]
    },
    {
      "label": "(b)(i)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "A1",
          "text": "acceleration $= 9.8\\text{ m s}^{-2}$"
        }
      ]
    },
    {
      "label": "(b)(ii)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "B1",
          "text": "air resistance (acting on sphere) increases"
        },
        {
          "tag": "B1",
          "text": "resultant force (on sphere) decreases"
        },
        {
          "tag": "B1",
          "text": "(magnitude of) acceleration decreases"
        }
      ]
    },
    {
      "label": "(c)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "C1",
          "text": "$F = ma$ $= 4.0 \\times 1.9$ $(= 7.6\\text{ N})$"
        },
        {
          "tag": "A1",
          "text": "resistive force $= (4.0 \\times 9.81) - (4.0 \\times 1.9)$ $= 32\\text{ N}$"
        }
      ]
    }
  ]
}
